create or replace function public.business_can_manage(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $function$ select exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager')) or exists(select 1 from public.profiles p where p.id=auth.uid() and coalesce(p.is_admin,false)); $function$;
create or replace function public.business_advanced_allowed(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $function$ select exists(select 1 from public.businesses b where b.id=p_business_id and b.business_tier::text in ('growth','enterprise','fleet')) or exists(select 1 from public.profiles p where p.id=auth.uid() and coalesce(p.is_admin,false)); $function$;
revoke all on function public.business_can_manage(uuid) from public; grant execute on function public.business_can_manage(uuid) to authenticated;
revoke all on function public.business_advanced_allowed(uuid) from public; grant execute on function public.business_advanced_allowed(uuid) to authenticated;
